style.css:
/* Mac 系统 Chrome 字体渲染优化 - 强制细体增强版 */
*:not([class*="icon"]):not(i):not([class*="fa"]) {
    /* 1. 强制细体 (保留你喜欢的设置) */
    /* 在 Mac 上，这会让粗体标题变成清秀的细体 */
    font-weight: 400 !important;

    /* 2. Mac 核心抗锯齿 (最重要的一行) */
    /* -webkit- 是给 Chrome 用的 */
    /* -moz-osx- 是专门激活 macOS 系统级灰度抗锯齿的 */
    /* 加上这行，Mac 上的字才会变得像纸上印刷一样锐利 */
    -webkit-font-smoothing: antialiased !important;
    -moz-osx-font-smoothing: grayscale !important;

    /* 3. 阴影微调 */
    /* Mac 屏幕素质高，不需要 0.1px 的位移，直接 0 0 就很立体 */
    /* 0.2 的透明度在 Mac Retina 屏上非常舒服，模拟墨水感 */
    text-shadow: 0 0 1px rgba(0, 0, 0, 0.2) !important;
}

/* 4. 修复输入框和代码块 */
/* 避免在输入文字时，光标因为阴影产生视觉错位 */
input, textarea, pre, code {
    text-shadow: none !important;
}
